// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));
        bool ok;
        vm.prank(attacker);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertFalse(ok);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address _newDistributor) public {
        require(_newDistributor != address(0), "distributor zero");
        c.setRewardDistributor(_newDistributor);
        assert(c.rewardDistributor() == _newDistributor);
    }
}
